import 'dart:async';import 'package:flutter/material.dart';import '../auth/auth_notifier.dart';import '../models/app_user.dart';import 'package:provider/provider.dart';import 'package:go_router/go_router.dart';import '../models/simple_query.dart';import '../state/load_status.dart';import '../state/reference_list_notifiers.dart';import '../widgets/entity_table.dart';import '../widgets/list_state_view.dart';import '../widgets/pagination_bar.dart';

class ReferenceListScreen<T> extends StatefulWidget{final String title,route,createRoute;final SimpleQuery query;final BaseReferenceNotifier<T> notifier;final int Function(T) idOf;final bool Function(T)isDeleted;final String Function(T)primary;final List<TableColumnSpec<T>> columns;final String defaultSort;const ReferenceListScreen({super.key,required this.title,required this.route,required this.createRoute,required this.query,required this.notifier,required this.idOf,required this.isDeleted,required this.primary,required this.columns,this.defaultSort='name'});@override State<ReferenceListScreen<T>>createState()=>_S<T>();}
class _S<T> extends State<ReferenceListScreen<T>>{late final TextEditingController search;Timer? timer;@override void initState(){super.initState();search=TextEditingController(text:widget.query.search);WidgetsBinding.instance.addPostFrameCallback((_){widget.notifier.applyQuery(widget.query);});}@override void didUpdateWidget(covariant ReferenceListScreen<T> old){super.didUpdateWidget(old);if(old.query!=widget.query){search.text=widget.query.search;WidgetsBinding.instance.addPostFrameCallback((_){widget.notifier.applyQuery(widget.query);});}}@override void dispose(){timer?.cancel();search.dispose();super.dispose();}void go(SimpleQuery q){context.go(Uri(path:widget.route,queryParameters:q.toQueryParameters(defaultSort:widget.defaultSort)).toString());}void searchChanged(String v){timer?.cancel();timer=Timer(const Duration(milliseconds:350),(){if(mounted)go(widget.query.copyWith(search:v,page:1));});}
@override Widget build(BuildContext c){final n=widget.notifier;return AnimatedBuilder(animation:n,builder:(c,_){return Scaffold(appBar:AppBar(title:Text(widget.title),actions:[IconButton(onPressed:()=>context.go('/'),icon:const Icon(Icons.home_outlined))]),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Card(child:Padding(padding:const EdgeInsets.all(12),child:Wrap(spacing:10,runSpacing:10,children:[SizedBox(width:300,child:TextField(controller:search,onChanged:searchChanged,decoration:const InputDecoration(labelText:'Поиск',prefixIcon:Icon(Icons.search)))),FilterChip(label:const Text('Показывать удалённые'),selected:widget.query.includeDeleted,onSelected:(v)=>go(widget.query.copyWith(includeDeleted:v,page:1))),OutlinedButton.icon(onPressed:()=>go(SimpleQuery(sortField:widget.defaultSort)),icon:const Icon(Icons.filter_alt_off),label:const Text('Сбросить')),FilledButton.icon(onPressed:()=>context.go(widget.createRoute),icon:const Icon(Icons.add),label:const Text('Добавить'))]))),if(n.hasSelection)Card(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:Text('Выбрано: ${n.selected.length}')),FilledButton.icon(onPressed:()=>_deleteSelected(n),icon:const Icon(Icons.delete_sweep),label:const Text('Удалить выбранные'))]))),const SizedBox(height:8),Expanded(child:_body(n))])));});}
Widget _body(BaseReferenceNotifier<T> n){switch(n.status){case LoadStatus.idle:case LoadStatus.loading:return const Center(child:CircularProgressIndicator());case LoadStatus.error:return ErrorStateView(message:n.error??'Ошибка',onBackToNormal:()=>go(SimpleQuery(sortField:widget.defaultSort)));case LoadStatus.success:if(n.result.items.isEmpty)return EmptyStateView(onReset:()=>go(SimpleQuery(sortField:widget.defaultSort)));return Column(children:[Expanded(child:SingleChildScrollView(child:EntityTable<T>(items:n.result.items,idOf:widget.idOf,selected:n.selected,onToggleSelect:n.toggleSelection,isDeleted:widget.isDeleted,sortField:widget.query.sortField,sortAscending:widget.query.sortAscending,onSort:(f)=>go(widget.query.copyWith(sortField:f,sortAscending:f==widget.query.sortField?!widget.query.sortAscending:true,page:1)),columns:widget.columns,actions:(e){final auth=context.read<AuthNotifier>();return[IconButton(tooltip:'Карточка',onPressed:()=>context.go('${widget.route}/${widget.idOf(e)}'),icon:const Icon(Icons.open_in_new)),IconButton(tooltip:'Редактировать',onPressed:()=>context.go('${widget.route}/${widget.idOf(e)}/edit'),icon:const Icon(Icons.edit_outlined)),if(!widget.isDeleted(e))IconButton(tooltip:'Логически удалить',onPressed:()=>_del(n,e,false),icon:const Icon(Icons.archive_outlined)),if(auth.can(Permission.restoreRecords)&&widget.isDeleted(e))IconButton(tooltip:'Восстановить',onPressed:()=>n.restore(widget.idOf(e)),icon:const Icon(Icons.restore)),if(auth.can(Permission.hardDelete))IconButton(tooltip:'Удалить навсегда',onPressed:()=>_del(n,e,true),icon:const Icon(Icons.delete_forever))];}))),PaginationBar(page:n.result.page,totalPages:n.result.totalPages,total:n.result.total,size:n.result.size,onPageChanged:(p)=>go(widget.query.copyWith(page:p)),onSizeChanged:(s)=>go(widget.query.copyWith(size:s,page:1))) ]);}}
Future<bool>confirm(String t,String s)async=>await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(t),content:Text(s),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Отмена')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Подтвердить'))]))??false;Future<void>_deleteSelected(BaseReferenceNotifier<T> n)async{if(await confirm('Удалить выбранные?','Будет выполнено логическое удаление ${n.selected.length} записей.')){try{await n.deleteSelected();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}}Future<void>_del(BaseReferenceNotifier<T> n,T e,bool hard)async{if(await confirm(hard?'Удалить навсегда?':'Логически удалить?',hard?'Запись «${widget.primary(e)}» нельзя будет восстановить.':'Запись «${widget.primary(e)}» можно будет восстановить.')){try{hard?await n.hardDelete(widget.idOf(e)):await n.softDelete(widget.idOf(e));}catch(err){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$err')));}}}}
